/// How many there are.
pub const UNAIDED_COUNT: usize = 3227;

/// Implements part of the calls-nothing family.
///
/// What one routine does, if it is one of these.
#[must_use]
pub fn routine_at(routine: u32) -> Option<&'static Routine> {
    UNAIDED
        .binary_search_by_key(&routine, |held| held.routine)
        .ok()
        .map(|at| &UNAIDED[at])
}

/// Implements part of the calls-nothing family.
///
/// How deep one routine goes. Zero means nothing sits inside anything.
#[must_use]
pub fn deepest(held: &Routine) -> u8 {
    held.steps.iter().map(|step| step.depth).max().unwrap_or(0)
}

/// Implements part of the calls-nothing family.
///
/// Whether a routine really reaches its end without calling anything.
///
/// False for the few that call through a thunk with no recovered function
/// behind it: something is called there, it just cannot be named.
#[must_use]
pub const fn calls_nothing_at_all(held: &Routine) -> bool {
    !held.through_a_thunk
}

/// Implements part of the calls-nothing family.
///
/// Whether a step is a branch reached because the questions before it failed.
#[must_use]
pub const fn is_a_fallback(step: &Step) -> bool {
    matches!(
        step.does,
        Does::Asking(Asks::Otherwise) | Does::AskingOtherwise(_)
    )
}

/// Implements part of the calls-nothing family.
///
/// What share of all the steps here are reached only because something failed.
///
/// Higher than in the routines that call things: where those work through a
/// sequence, these choose between answers.
#[must_use]
pub fn share_of_fallbacks() -> f64 {
    let steps: Vec<&Step> = UNAIDED.iter().flat_map(|held| held.steps.iter()).collect();
    if steps.is_empty() {
        return 0.0;
    }
    let fallbacks = steps.iter().filter(|step| is_a_fallback(step)).count();
    #[expect(
        clippy::cast_precision_loss,
        reason = "counts of a few thousand, well inside what a double holds exactly"
    )]
    {
        fallbacks as f64 / steps.len() as f64
    }
}

/// Implements part of the calls-nothing family.
///
/// Every routine that is one loop and nothing else.
///
/// A scan: something is walked to find a value or a length, and the whole of
/// the work sits in the loop's own condition.
#[must_use]
pub fn scans() -> Vec<&'static Routine> {
    UNAIDED
        .iter()
        .filter(|held| {
            held.steps.len() == 1
                && matches!(
                    held.steps[0].does,
                    Does::Repeatedly | Does::RepeatedlyAtLeastOnce
                )
        })
        .collect()
}

/// Implements part of the calls-nothing family.
///
/// Every routine that is a single step of any kind.
#[must_use]
pub fn single_step() -> Vec<&'static Routine> {
    UNAIDED
        .iter()
        .filter(|held| held.steps.len() == 1)
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_table_holds() {
        assert_eq!(UNAIDED.len(), UNAIDED_COUNT);
    }

    #[test]
    fn the_table_is_sorted_so_it_can_be_searched() {
        assert!(
            UNAIDED
                .windows(2)
                .all(|pair| pair[0].routine < pair[1].routine)
        );
    }

    #[test]
    fn a_routine_can_be_found_by_its_address() {
        let known = UNAIDED[0].routine;

        assert!(routine_at(known).is_some());
        assert!(routine_at(0).is_none());
    }

    #[test]
    fn not_one_of_them_calls_a_recovered_function() {
        // Which is the whole of what puts them in this table.
        for held in &UNAIDED {
            for step in held.steps {
                assert!(step.calls.is_empty(), "{:#010X}", held.routine);
            }
        }
    }

    #[test]
    fn but_a_few_of_them_do_call_through_a_thunk() {
        // Something is called there; it just cannot be named. Saying "calls
        // nothing" of those would be claiming more than was seen.
        let thunked = UNAIDED.iter().filter(|held| held.through_a_thunk).count();

        assert!(thunked > 0);
        assert!(thunked < UNAIDED.len() / 10);
        for held in UNAIDED.iter().filter(|held| held.through_a_thunk).take(20) {
            assert!(!calls_nothing_at_all(held));
        }
    }

    #[test]
    fn none_of_these_is_in_any_of_the_tables_that_do_call_things() {
        for held in UNAIDED.iter().take(400) {
            assert!(crate::nested_routines::routine_at(held.routine).is_none());
            assert!(crate::deeper_routines::routine_at(held.routine).is_none());
            assert!(crate::looping_routines::routine_at(held.routine).is_none());
        }
    }

    #[test]
    fn the_depths_of_a_routine_only_ever_step_down_by_one() {
        for held in &UNAIDED {
            let mut last = 0_u8;
            for step in held.steps {
                assert!(step.depth <= last + 1, "{:#010X}", held.routine);
                last = step.depth;
            }
        }
    }

    #[test]
    fn they_fall_back_more_often_than_routines_that_call_things() {
        // Where a routine that calls things works through a sequence, one of
        // these chooses between answers, and choosing is what an else is for.
        let here = share_of_fallbacks();
        let there = {
            let steps: Vec<&Step> = crate::nested_routines::NESTED
                .iter()
                .flat_map(|held| held.steps.iter())
                .collect();
            let fallbacks = steps.iter().filter(|step| is_a_fallback(step)).count();
            #[expect(
                clippy::cast_precision_loss,
                reason = "counts of a few tens of thousands, exact in a double"
            )]
            {
                fallbacks as f64 / steps.len() as f64
            }
        };

        assert!(here > there, "{here} against {there}");
    }

    #[test]
    fn many_of_them_are_a_single_step() {
        let alone = single_step().len();

        assert!(alone * 4 > UNAIDED.len(), "{alone} of {}", UNAIDED.len());
        for held in single_step().iter().take(100) {
            assert_eq!(held.steps.len(), 1);
        }
    }

    #[test]
    fn some_of_them_are_one_loop_and_nothing_else() {
        // A scan: the whole of the work sits in the loop's own condition.
        let scanning = scans();

        assert!(!scanning.is_empty());
        for held in scanning.iter().take(50) {
            assert_eq!(held.steps.len(), 1);
            assert!(matches!(
                held.steps[0].does,
                Does::Repeatedly | Does::RepeatedlyAtLeastOnce
            ));
        }
    }

    #[test]
    fn a_scan_is_also_a_single_step_routine() {
        let scanning = scans().len();
        let alone = single_step().len();

        assert!(scanning <= alone, "{scanning} against {alone}");
    }

    #[test]
    fn no_routine_here_is_empty() {
        for held in &UNAIDED {
            assert!(!held.steps.is_empty(), "{:#010X}", held.routine);
        }
    }

    #[test]
    fn a_plain_question_is_not_counted_as_a_fallback() {
        let plain = Step {
            depth: 0,
            does: Does::Asking(Asks::IsSomething),
            calls: &[],
        };

        assert!(!is_a_fallback(&plain));
    }

    #[test]
    fn every_routine_is_listed_once() {
        let mut routines: Vec<u32> = UNAIDED.iter().map(|held| held.routine).collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }
}
